window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d4f397ea4ef07ce"]={"versions": [{"id": "FIG-5d4f397ea4ef07ce", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellfenster (Blockschaltbild) zur Veranschaulichung der Modellierungsrichtlinien für AUTOSAR Software-Komponenten. Dargestellt ist eine Systemkomposition innerhalb des Modells <code>AUTOSAR_sensor_actuator_example/sensor actuator</code>, in der Sensor- und Aktor-Komponenten über atomare Software-Komponenten (Application Software Components) im Simulink-Signalfluss miteinander interagieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell enthält vier Komponentenblöcke mit Ports und gerichteten Signalverbindungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Sensor Software Component</strong>: Bereitstellende Komponente mit drei Ausgangsports: <code>P-Port1</code>, <code>P-Port2</code>, <code>P-Port3</code>.</li>\n<li><strong>Atomic Software Component1</strong>: Verarbeitende Komponente mit drei Eingangsports (<code>R-Port1</code>, <code>R-Port2</code>, <code>R-Port3</code>) und drei Ausgangsports (<code>P-Port1</code>, <code>P-Port2</code>, <code>P-Port3</code>).</li>\n<li><strong>Atomic Software Component2</strong>: Zwischengeschaltete Komponente mit Eingangsport <code>R-Port1</code> und Ausgangsport <code>P-Port1</code>.</li>\n<li><strong>Actuator Software Component</strong>: Empfangende Komponente mit drei Eingangsports: <code>R-Port1</code>, <code>R-Port2</code>, <code>R-Port3</code>.</li>\n</ul>\n<p class=\"fig-p\">Verbindungen und Signalbeschriftungen:</p>\n<ul class=\"fig-list\">\n<li><code>P-Port1</code> (Sensor) verbindet auf <code>R-Port1</code> (Atomic Software Component1).</li>\n<li><code>P-Port2</code> (Sensor) verbindet auf <code>R-Port2</code> (Atomic Software Component1).</li>\n<li><code>P-Port3</code> (Sensor) verbindet auf <code>R-Port3</code> (Atomic Software Component1).</li>\n<li><code>P-Port1</code> (Atomic Software Component1) führt als Doppellinie (Bus/Vektor) mit Signalbeschriftung <code>&lt;DataElement_a, DataElement_b&gt;</code> zu <code>R-Port1</code> (Atomic Software Component2).</li>\n<li><code>P-Port1</code> (Atomic Software Component2) führt mit Signalbeschriftung <code>&lt;DataElement1, DataElement2&gt;</code> zu <code>R-Port1</code> (Actuator Software Component).</li>\n<li><code>P-Port2</code> (Atomic Software Component1) führt mit Signalbeschriftung <code>&lt;DataElement_c, DataElement_d&gt;</code> direkt zu <code>R-Port2</code> (Actuator Software Component).</li>\n<li><code>P-Port3</code> (Atomic Software Component1) führt mit Signalbeschriftung <code>&lt;DataElement_Act1, DataElement_Act2&gt;</code> direkt zu <code>R-Port3</code> (Actuator Software Component).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Gerichteter Signal- und Datenfluss von links nach rechts: Sensordaten werden von der <code>Sensor Software Component</code> erfasst und über die Ports an <code>Atomic Software Component1</code> übergeben. Diese transformiert und routet die Daten: Ein Teilpfad wird über <code>Atomic Software Component2</code> weiterverarbeitet und an die <code>Actuator Software Component</code> geleitet; zwei weitere Datenströme werden direkt von <code>Atomic Software Component1</code> zur Ansteuerung an die <code>Actuator Software Component</code> übertragen. Das Modell ist für eine kontinuierliche/diskrete Simulation mit Zeitschritt <code>10.0</code> und Solver <code>ode3</code> konfiguriert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als Implementierungs- und Modellierungsbeispiel für den AUTOSAR Simulink Styleguide. Es demonstriert die Abbildung von AUTOSAR-Port-Schnittstellen (P-Ports und R-Ports) sowie die Bündelung von Datenelementen (Sender-Receiver-Interfaces mit mehreren <code>DataElements</code>) auf Simulink-Signalleitungen bzw. -Busse zwischen Sensor-, Anwendungs- und Aktor-Softwarekomponenten.</p>"}, {"id": "FIG-a52b1c34a0e7c5e4", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellfenster (Blockschaltbild) zur Veranschaulichung der Modellierungsrichtlinien für AUTOSAR Software-Komponenten. Dargestellt ist eine Systemkomposition innerhalb des Modells <code>AUTOSAR_sensor_actuator_example/sensor actuator</code>, in der Sensor- und Aktor-Komponenten über atomare Software-Komponenten (Application Software Components) im Simulink-Signalfluss miteinander interagieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell enthält vier Komponentenblöcke mit Ports und gerichteten Signalverbindungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Sensor Software Component</strong>: Bereitstellende Komponente mit drei Ausgangsports: <code>P-Port1</code>, <code>P-Port2</code>, <code>P-Port3</code>.</li>\n<li><strong>Atomic Software Component1</strong>: Verarbeitende Komponente mit drei Eingangsports (<code>R-Port1</code>, <code>R-Port2</code>, <code>R-Port3</code>) und drei Ausgangsports (<code>P-Port1</code>, <code>P-Port2</code>, <code>P-Port3</code>).</li>\n<li><strong>Atomic Software Component2</strong>: Zwischengeschaltete Komponente mit Eingangsport <code>R-Port1</code> und Ausgangsport <code>P-Port1</code>.</li>\n<li><strong>Actuator Software Component</strong>: Empfangende Komponente mit drei Eingangsports: <code>R-Port1</code>, <code>R-Port2</code>, <code>R-Port3</code>.</li>\n</ul>\n<p class=\"fig-p\">Verbindungen und Signalbeschriftungen:</p>\n<ul class=\"fig-list\">\n<li><code>P-Port1</code> (Sensor) verbindet auf <code>R-Port1</code> (Atomic Software Component1).</li>\n<li><code>P-Port2</code> (Sensor) verbindet auf <code>R-Port2</code> (Atomic Software Component1).</li>\n<li><code>P-Port3</code> (Sensor) verbindet auf <code>R-Port3</code> (Atomic Software Component1).</li>\n<li><code>P-Port1</code> (Atomic Software Component1) führt als Doppellinie (Bus/Vektor) mit Signalbeschriftung <code>&lt;DataElement_a, DataElement_b&gt;</code> zu <code>R-Port1</code> (Atomic Software Component2).</li>\n<li><code>P-Port1</code> (Atomic Software Component2) führt mit Signalbeschriftung <code>&lt;DataElement1, DataElement2&gt;</code> zu <code>R-Port1</code> (Actuator Software Component).</li>\n<li><code>P-Port2</code> (Atomic Software Component1) führt mit Signalbeschriftung <code>&lt;DataElement_c, DataElement_d&gt;</code> direkt zu <code>R-Port2</code> (Actuator Software Component).</li>\n<li><code>P-Port3</code> (Atomic Software Component1) führt mit Signalbeschriftung <code>&lt;DataElement_Act1, DataElement_Act2&gt;</code> direkt zu <code>R-Port3</code> (Actuator Software Component).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Gerichteter Signal- und Datenfluss von links nach rechts: Sensordaten werden von der <code>Sensor Software Component</code> erfasst und über die Ports an <code>Atomic Software Component1</code> übergeben. Diese transformiert und routet die Daten: Ein Teilpfad wird über <code>Atomic Software Component2</code> weiterverarbeitet und an die <code>Actuator Software Component</code> geleitet; zwei weitere Datenströme werden direkt von <code>Atomic Software Component1</code> zur Ansteuerung an die <code>Actuator Software Component</code> übertragen. Das Modell ist für eine kontinuierliche/diskrete Simulation mit Zeitschritt <code>10.0</code> und Solver <code>ode3</code> konfiguriert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als Implementierungs- und Modellierungsbeispiel für den AUTOSAR Simulink Styleguide. Es demonstriert die Abbildung von AUTOSAR-Port-Schnittstellen (P-Ports und R-Ports) sowie die Bündelung von Datenelementen (Sender-Receiver-Interfaces mit mehreren <code>DataElements</code>) auf Simulink-Signalleitungen bzw. -Busse zwischen Sensor-, Anwendungs- und Aktor-Softwarekomponenten.</p>"}], "trans": [{"from": "FIG-5d4f397ea4ef07ce", "to": "FIG-a52b1c34a0e7c5e4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
